import numpy as np


def gradient(A, y, w):
    A, y, w = [np.asarray(v, dtype=float) for v in [A, y, w]]
    if (
        A.ndim != 2
        or not len(A)
        or y.shape != (A.shape[0],)
        or w.shape != (A.shape[1],)
    ):
        raise ValueError("Exact shape contract required")
    if any(not np.isfinite(v).all() for v in [A, y, w]):
        raise ValueError("Finite values required")
    return A.T @ (A @ w - y) / len(y)


print(gradient([[1, 0], [1, 1], [1, 2]], [1, 2, 2], [0, 0])[1])
